    // Simplified period finding for demonstration
    operation ModularExp(a : Int, x : Int, N : Int) : Int {
        mutable result = 1;
        mutable base = a % N;
        mutable exp = x;

        while (exp > 0) {
            if (exp &&& 1) == 1 {
                set result = (result * base) % N;
            }
            set base = (base * base) % N;
            set exp = exp >>> 1;
        }

        return result;
    }

    // Simplified QFT implementation
    operation QFT(qubits : Qubit[]) : Unit is Adj {
        let n = Length(qubits);

        for (i in 0..n-1) {
            H(qubits[i]);

            for (j in i+1..n-1) {
                let angle = PI() / IntAsDouble(2^(j-i));
                Controlled R1([qubits[j]], (angle, qubits[i]));
            }
        }

        // Reverse order for standard QFT output
        for (i in 0..n/2-1) {
            Swap(qubits[i], qubits[n-1-i]);
        }
    }

